# Reopen a closed period, making its due-total live again. An unknown period is a 400; one not
# closed, or a reopen by a role the permission matrix does not allow (a steward by default), is a 409.
load:
  class: net.officefloor.hq.app.period.LoadPeriod
  govern: [ transaction ]
  next: reopen
reopen:
  class: net.officefloor.hq.app.period.ReopenPeriod
  govern: [ transaction ]
  next: record
# Audit only once the period is reopened: a refused reopen writes no line.
record:
  class: net.officefloor.hq.app.period.RecordPeriodReopened
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithReopenedPeriod
  govern: [ transaction ]
# Close a period (an open or soft-closed one), fixing its due-total afresh. An unknown period is a
# 400; one already closed (not soft-closed), or a close by a role the permission matrix does not
# allow, is a 409.
load:
  class: net.officefloor.hq.app.period.LoadPeriod
  govern: [ transaction ]
  next: close
close:
  class: net.officefloor.hq.app.period.ClosePeriod
  govern: [ transaction ]
  next: record
# Audit only once the period is closed: a refused close writes no line.
record:
  class: net.officefloor.hq.app.period.RecordPeriodClosed
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.period.RespondWithClosedPeriod
  govern: [ transaction ]
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.settings.Settings;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Reopens a closed period, making its due-total live again. Only the roles the permission matrix allows may reopen a period (a steward by default),
 *  and only a closed one can be reopened. Publishes the reopened period. */
public class ReopenPeriod {
    public void reopen(@Val Period period, @Val PeriodCloseRequest request, Periods periods, Settings settings,
            Out<ReopenedPeriod> reopened) throws PeriodClosedException {
        if (!settings.allows(period.sheetId(), "reopen", request.user())) {
            throw new PeriodClosedException("Your role may not reopen period " + period.name());
        }
        if (!period.closed()) throw new PeriodClosedException("Period " + period.name() + " is not closed");
        periods.reopen(period);
        reopened.set(new ReopenedPeriod(new Period(period.sheetId(), period.name(), period.from(), period.to(), period.cap())));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Runs after the period is reopened, so a refused reopen writes no audit line. */
public class RecordPeriodReopened {
    public void record(@Val PeriodCloseRequest request, @Val ReopenedPeriod reopened, Audit audit) {
        Period period = reopened.period();
        audit.record("PERIOD_REOPENED sheet=" + period.sheetId() + " by=" + request.user()
                + " period=" + period.name());
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithReopenedPeriod {
    public void respond(@Val ReopenedPeriod reopened, ObjectResponse<PeriodResponse> response) {
        response.send(PeriodResponse.from(reopened.period()));
    }
}
package net.officefloor.hq.app.period;

/** The period as it is once reopened. */
public record ReopenedPeriod(Period period) {
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.sheet.InvalidSheetRequestException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads who closes or reopens the period and loads it. */
public class LoadPeriod {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("name") String name,
            @RequestBody PeriodCloseRequest request, Periods periods, Out<PeriodCloseRequest> body,
            Out<Period> periodOut) throws InvalidSheetRequestException {
        Period period = periods.find(sheetId, name);
        if (period == null) throw new InvalidSheetRequestException("No period named " + name);
        body.set(request == null ? new PeriodCloseRequest(null) : request);
        periodOut.set(period);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A period of a sheet: its name, unique on the sheet, and its from and to dates, inclusive. A
 *  closed period keeps the due-total it had when it was closed (`closedTotal`). A soft-closed one
 *  (`closed` and `soft`) keeps it too, but claims dated in it can still be changed. A period may cap
 *  how many OPEN or PENDING claims due by in it each person may have (`cap`; null for none). */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal,
        boolean soft, Integer cap) {

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal,
            boolean soft) {
        this(sheetId, name, from, to, closed, closedTotal, soft, null);
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed, BigDecimal closedTotal) {
        this(sheetId, name, from, to, closed, closedTotal, false);
    }

    /** A new, open period. */
    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this(sheetId, name, from, to, false, null);
    }

    /** A new, open period with a cap (null for none). */
    public Period(String sheetId, String name, LocalDate from, LocalDate to, Integer cap) {
        this(sheetId, name, from, to, false, null, false, cap);
    }

    /** Whether the period is closed outright, not soft-closed: no claim dated in it can change. */
    public boolean hardClosed() {
        return closed && !soft;
    }

    /** Whether the two periods share a day. */
    public boolean overlaps(Period other) {
        return !from.isAfter(other.to) && !other.from.isAfter(to);
    }

    /** Whether the date falls in the period. */
    public boolean contains(LocalDate date) {
        return !date.isBefore(from) && !date.isAfter(to);
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.LinkedHashMap;
import java.util.Map;

/** A period as the screen sees it: its dates as yyyy-mm-dd, whether it is closed and, when it is,
 *  the due-total fixed when it was closed and each person's (`closedPersonTotals`, by person id;
 *  a person not in it shows 0.00) and each person's carried figure (`closedPersonCarried`, alike), whether the close is a soft close, and its cap (null for none),
 *  and each person's opening balance for it (`openings`, by person id; a person with none is absent). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<String, String> closedPersonTotals, Map<String, String> closedPersonCarried, boolean soft, Integer cap,
        Map<String, String> openings) {
    public static PeriodResponse from(Period period) {
        return from(period, Map.of(), Map.of(), Map.of());
    }

    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals,
            Map<Long, BigDecimal> personCarried) {
        return from(period, personTotals, personCarried, Map.of());
    }

    public static PeriodResponse from(Period period, Map<Long, BigDecimal> personTotals,
            Map<Long, BigDecimal> personCarried, Map<Long, BigDecimal> personOpenings) {
        Map<String, String> totals = new LinkedHashMap<>();
        personTotals.forEach((id, total) -> totals.put(id.toString(), total.setScale(2).toPlainString()));
        Map<String, String> carried = new LinkedHashMap<>();
        personCarried.forEach((id, figure) -> carried.put(id.toString(), figure.setScale(2).toPlainString()));
        Map<String, String> openings = new LinkedHashMap<>();
        personOpenings.forEach((id, amount) -> openings.put(id.toString(), amount.setScale(2).toPlainString()));
        return new PeriodResponse(period.name(), period.from().toString(), period.to().toString(), period.closed(),
                period.closedTotal() == null ? null : period.closedTotal().setScale(2).toPlainString(), totals, carried,
                period.soft(), period.cap(), openings);
    }
}
